INSERT INTO `tb_note_barang` (`id_nt_barang`, `kd_po`, `kd_suplier`, `isi_note`, `color_box`, `create_at`) VALUES
(1, 'MKPO010424JAWAA010001', 'JAWAA01', '*Harga Include PPN 11%\n*Bonus Kaos Pinamec, 1 L = 1 kaos (1375 pcs)', '', '0000-00-00 00:00:00'),
(2, 'KPOREV0104240003', 'JAWAA01', '*Revisi isi per box pinamec 1 ltr & bonus kaos\n*Harga Include PPN 11%\r\n*Bonus Kaos Pinamec, 1 L = 1 kaos (1625 pcs)', '', '0000-00-00 00:00:00'),
(3, 'NKPO010424WINON010004', 'WINON01', '*Mohon Label Expired Date sudah tertempel di tiap-tiap Pack\n*Barang terdiri dari 1 nomor Lot, dengan tgl expired terpanjang', '', '0000-00-00 00:00:00'),
(4, 'MKPO010424KARUN030005', 'KARUN03', '* Harga Include PPN 11%\n* Mohon diatur 2x kirim: \r\n- Pengiriman 1 sebelum libur Idul Fitri:\r\n   Benang pe mlg : 5 ton\r\n   Tali gawar 989 600 gr : 208 box \r\n- Pengiriman 2 setelah libur idul fitri: \r\n   Benang pe mlg : 5 ton \r\n\r\n*KIU terakhir terima barang tanggal 5 April 2024. Disarankan sudah tiba di KIU sebelum tanggal 5 April 2024. KIU aktif operasional kembali tanggal 15 April 2024. Tks. ', '', '0000-00-00 00:00:00'),
(5, 'KPOREV0104240006', 'AGRIC02', '*Revisi total harga PO sudah ditambah PPN 11%\n*PO untuk Nuansa Tani kirim ke Gudang KIU Jember\r\n* Bonus Produk 4% di bawakan bersamaan dgn pengiriman barang:\r\n- Spontan 200 ml = 20 box\r\n- Spontan 500 ml =  28 box 8 btl \r\n- Spontan 1 ltr = 4 box\r\n* Apabila tidak dikirim bersama dengan bonus, mohon jangan dikirim\r\ndahulu barangnya.\r\n* Mohon diatur kirim:\r\n-Pengiriman 1 tanggal 15 April 2024:\r\n   -Spontan 200 ml  400 box\r\n   -Spontan 500 ml 400 box\r\n- Pengiriman 2 dikirim tanggal 30 April 2024', '', '0000-00-00 00:00:00'),
(6, 'KPOREV0104240007', 'AGRIC02', '*Revisi total harga PO sudah ditambah PPN 11%\n*PO untuk Nuansa Tani kirim ke Gudang KIU Jember\r\n* Bonus Produk 4% di bawakan bersamaan dgn pengiriman barang:\r\n- Spontan 200 ml = 20 box\r\n- Spontan 500 ml =  28 box 8 btl \r\n- Spontan 1 ltr = 4 box\r\n* Apabila tidak dikirim bersama dengan bonus, mohon jangan dikirim\r\ndahulu barangnya.\r\n* Mohon diatur kirim:\r\n-Pengiriman 1 tanggal 15 April 2024:\r\n   -Spontan 200 ml  400 box\r\n   -Spontan 500 ml 400 box\r\n- Pengiriman 2 dikirim tanggal 30 April 2024', '', '0000-00-00 00:00:00'),
(7, 'NKPO020424SONGG010001', 'SONGG01', '* Barang+Bonus 12 dos TANI kirim ke KIU-Jember\n* Mohon dikirimkan juga Kaos EM, tks', '', '0000-00-00 00:00:00'),
(8, 'NKPO020424SONGG020002', 'SONGG02', '* Barang+Bonus 12 dos TANI kirim ke KIU-Jember\n* Mohon dikirimkan juga Kaos EM, tks', '', '0000-00-00 00:00:00'),
(9, 'NKPO030424NUFAR010001', 'NUFAR01', '* DK 5%\n* DR 8%\r\n* Program bantuan Champion 91.06 kg', '', '0000-00-00 00:00:00'),
